import json,pathlib
ROOT=pathlib.Path(__file__).parent

def scenario(id,title,premise,initial,recipes,stages,locations=(),sources=(),labels=None,notes=()):
    labels=labels or {}; ids=set(initial)
    for s in stages:
        for c in s.get('caches',[]): ids.update(c['items'])
    for r in recipes:
        ids.update(v for k,v in r.items() if k in ('a','b','out') and not v.startswith('@'))
    result={'schemaVersion':1,'id':id,'title':title,'premise':premise,'items':[{'id':x,'label':labels.get(x,x.replace('-',' ').capitalize())} for x in sorted(ids)],'locations':[{'id':p,'label':label} for p,label in locations],'initialItems':initial,'recipes':recipes,'stages':stages,'sources':list(sources),'notes':list(notes)}
    (ROOT/(id+'.json')).write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
    return result

def rec(a,b,out,at=None,desc=None,source=None,retire=()):
    r={'id':out,'a':a,'b':b,'out':out}
    if at:r['at']=at
    if desc:r['description']=desc
    if source:r['sources']=[source]
    if retire:r['retire']=[{'item':x,'reason':'The original is incorporated into this recognizable derived thing.'} for x in retire]
    return r

def cache(id,label,narrative,*items):return dict(id=id,label=label,narrative=narrative,items=list(items))
def goal(item,text=None,location=None):return dict(id=item+'-goal',text=text or 'Make '+item.replace('-',' ')+'.',kind='place' if location else 'create',item=item,**({'location':location} if location else {}))
def stage(id,title,speaker,text,goals,locations=(),caches=()):return dict(id=id,title=title,speaker=speaker,motivation=text,area=dict(id=id+'-area',label=title,travelText='We are taking the useful things with us. Earlier creations remain where we made them.'),locations=list(locations),caches=list(caches),objectives=goals)
def source(id,title,url,note=''):return dict(id=id,title=title,url=url,note=note)
